#!/usr/bin/env bash
set -euo pipefail

APP_DIR="${APP_DIR:-/opt/source-latency-profiler}"
RESULTS_BUCKET="${RESULTS_BUCKET:?Set RESULTS_BUCKET to your profiler results bucket name}"
NULLONE_ENV_FILE="${NULLONE_ENV_FILE:-/etc/source-latency-profiler/nullone.env}"
export NULLONE_ENV_FILE

if [[ "${EUID}" -ne 0 ]]; then
  echo "Run as root (sudo) to install systemd units." >&2
  exit 1
fi

# install_unit is kept for non-strategy units (janitor, diagnostic) that are
# not generated by install-strategy.sh.
install_unit() {
  local source_name="$1"
  local target_name="${2:-$1}"
  local path="${APP_DIR}/scripts/${source_name}"
  if [[ ! -f "${path}" ]]; then
    echo "Missing unit template: ${path}" >&2
    exit 1
  fi
  sed "s/source-latency-profiler-results-CHANGE_ME/${RESULTS_BUCKET}/g" "${path}" \
    >"/etc/systemd/system/${target_name}"
}

INSTALL_STRATEGY="${APP_DIR}/scripts/install-strategy.sh"

ensure_nullone_ready() {
  if [[ ! -f "${NULLONE_ENV_FILE}" ]]; then
    echo "Missing NullOne env file: ${NULLONE_ENV_FILE}" >&2
    echo "Run deploy_orchestrator_host.sh with NULLONE_* configuration first." >&2
    exit 1
  fi
  # shellcheck source=/dev/null
  source "${NULLONE_ENV_FILE}"
  local bin="${NULLONE_BIN:-nullone}"
  if [[ "${bin}" == */* ]]; then
    if [[ ! -x "${bin}" ]]; then
      echo "NULLONE_BIN is not executable: ${bin}" >&2
      exit 1
    fi
  elif ! command -v "${bin}" >/dev/null 2>&1; then
    echo "nullone binary not found on PATH (NULLONE_BIN=${bin})." >&2
    exit 1
  fi
  if ! "${bin}" --help >/dev/null 2>&1; then
    echo "nullone binary exists but '--help' failed (NULLONE_BIN=${bin})." >&2
    exit 1
  fi
}

ensure_nullone_ready

# ── Strategy units (generated via install-strategy.sh) ────────────────────────

# Production WNGSR scheduler — unit name "prod" preserves the existing deployed name.
"${INSTALL_STRATEGY}" \
  --strategy  strategies/nullone-wngsr-kalshi.yaml \
  --calendar  calendars/kalshi-wngsr-2026.json \
  --unit-name prod \
  --secrets-prefix nullone/prod \
  --enable

# Sandbox / drill scheduler — installed but not auto-enabled.
"${INSTALL_STRATEGY}" \
  --strategy  strategies/nullone-wngsr-kalshi-sandbox.yaml \
  --unit-name sandbox \
  --secrets-prefix nullone/prod \
  --extra-args "--diagnostics hot-path --samples 1"

# WPSR crude oil scheduler — auto-enabled (same trust level as WNGSR).
"${INSTALL_STRATEGY}" \
  --strategy  strategies/nullone-wpsr-kalshi.yaml \
  --calendar  calendars/kalshi-wpsr-2026.json \
  --secrets-prefix nullone/prod \
  --enable

# CPI scheduler — installed but not enabled (pending NullOne discover interface).
"${INSTALL_STRATEGY}" \
  --strategy  strategies/nullone-cpi-kalshi.yaml \
  --calendar  calendars/kalshi-cpi-2026.json \
  --secrets-prefix nullone/prod

# NFP scheduler — installed but not enabled.
"${INSTALL_STRATEGY}" \
  --strategy  strategies/nullone-nfp-kalshi.yaml \
  --calendar  calendars/kalshi-nfp-2026.json \
  --secrets-prefix nullone/prod

# FOMC scheduler — installed but not enabled.
"${INSTALL_STRATEGY}" \
  --strategy  strategies/nullone-fomc-kalshi.yaml \
  --calendar  calendars/kalshi-fomc-2026.json \
  --secrets-prefix nullone/prod

# ── Non-strategy units (static templates) ────────────────────────────────────
install_unit source-latency-profiler-janitor.service
install_unit source-latency-profiler-janitor.timer
install_unit source-latency-profiler-diagnostic.service
install_unit source-latency-profiler-diagnostic.timer

systemctl daemon-reload
systemctl enable --now source-latency-profiler-janitor.timer

echo ""
echo "Installed and enabled: prod (WNGSR), wpsr, janitor timers."
echo "Installed but NOT enabled: sandbox, cpi, nfp, fomc, diagnostic."
echo ""
echo "Enable sandbox drills (set event_time in the YAML first):"
echo "  sudo systemctl enable --now source-latency-profiler-scheduler-sandbox.timer"
echo ""
echo "Enable CPI/NFP/FOMC after NullOne discover interface is ready:"
echo "  sudo systemctl enable --now source-latency-profiler-scheduler-nullone-cpi-kalshi.timer"
echo "  sudo systemctl enable --now source-latency-profiler-scheduler-nullone-nfp-kalshi.timer"
echo "  sudo systemctl enable --now source-latency-profiler-scheduler-nullone-fomc-kalshi.timer"
echo ""
echo "Enable daily hot-path diagnostic:"
echo "  sudo systemctl enable --now source-latency-profiler-diagnostic.timer"
echo ""
echo "To install additional paper/prod strategies without editing this script:"
echo "  sudo APP_DIR=${APP_DIR} RESULTS_BUCKET=${RESULTS_BUCKET} \\"
echo "    ${APP_DIR}/scripts/install-strategy.sh \\"
echo "      --strategy strategies/<name>.yaml \\"
echo "      --calendar calendars/<name>.json \\"
echo "      --enable"
